# THE RULE (every family): the words ALL its pieces' names start with, the slot noun (each name's last word) dropped, then the kind words
# Bark / Angler and any tier code dropped: "Maple Bark Helm" + "Maple Bark Cuirass" ... -> "Maple"; "Lead Cuirass" -> "Lead"; "Wheat Tunic"
# -> "Wheat"; "Copper Angler Boots" -> "Copper"; "Soft Leather Tunic" -> "Soft Leather". "" = no shared words (the caller falls back)
M(gsm, r"""
public static String setWords(String[] names) {
  if (names == null || names.length == 0) return "";
  String[] w0 = null;
  int n = 0;
  for (int i = 0; i < names.length; i++) {
    if (names[i] == null) return "";
    String[] w = names[i].trim().split("\\\\s+");
    if (w.length < 2) return "";
    if (w0 == null) { w0 = w; n = w.length - 1; continue; }
    int k = 0;
    while (k < n && k < w.length - 1 && w[k].equals(w0[k])) k++;
    n = k;
  }
  StringBuilder sb = new StringBuilder();
  for (int k = 0; w0 != null && k < n; k++) {
    if (kindWord(w0[k]) || isCode(w0[k])) continue;
    if (sb.length() > 0) sb.append(' ');
    sb.append(w0[k]);
  }
  return sb.toString();
}""")
